using System.Threading.Channels;

namespace Acme.Import;

public sealed class CustomerImporter(ICustomerStore store)
{
    public async Task ImportAsync(string path, CancellationToken ct)
    {
        var channel = Channel.CreateUnbounded<CustomerRow>();

        var producer = Task.Run(async () =>
        {
            await foreach (var line in File.ReadLinesAsync(path, ct))
            {
                channel.Writer.TryWrite(CustomerRow.Parse(line));
            }
        }, ct);

        var consumer = Task.Run(async () =>
        {
            while (true)
            {
                var row = await channel.Reader.ReadAsync(ct);
                await store.UpsertAsync(row, ct);
            }
        }, ct);

        await Task.WhenAll(producer, consumer);
    }
}

